-- customer_credential: Authentication credentials of a customer (passkeys, PIN, password, TOTP); secrets stored as hashes only
CREATE TABLE customer_credential (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  customer_id                  uuid NOT NULL REFERENCES customer(id),
  credential_type              varchar(40) NOT NULL CHECK (credential_type IN ('PASSKEY', 'PASSWORD', 'PIN', 'TOTP', 'SMS_OTP', 'BIOMETRIC_BINDING', 'SECURITY_QUESTION')),
  status                       varchar(40) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'LOCKED', 'EXPIRED', 'REVOKED')),
  customer_device_id           uuid REFERENCES customer_device(id),
  webauthn_credential_id       varchar(512),
  public_key                   text,
  sign_count                   bigint,
  secret_hash                  varchar(255),
  failed_attempts              integer NOT NULL DEFAULT 0,
  locked_until                 timestamptz,
  last_used_at                 timestamptz,
  expires_at                   timestamptz,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500)
);
COMMENT ON TABLE customer_credential IS 'Authentication credentials of a customer (passkeys, PIN, password, TOTP); secrets stored as hashes only';
COMMENT ON COLUMN customer_credential.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN customer_credential.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN customer_credential.created_at IS 'Creation time';
COMMENT ON COLUMN customer_credential.created_by IS 'Principal that created the row';
COMMENT ON COLUMN customer_credential.updated_at IS 'Last update time';
COMMENT ON COLUMN customer_credential.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN customer_credential.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN customer_credential.customer_id IS 'Customer';
COMMENT ON COLUMN customer_credential.credential_type IS 'Credential type';
COMMENT ON COLUMN customer_credential.status IS 'Status';
COMMENT ON COLUMN customer_credential.customer_device_id IS 'Device the credential is bound to';
COMMENT ON COLUMN customer_credential.webauthn_credential_id IS 'WebAuthn credential id (passkeys)';
COMMENT ON COLUMN customer_credential.public_key IS 'WebAuthn public key (COSE)';
COMMENT ON COLUMN customer_credential.sign_count IS 'WebAuthn signature counter';
COMMENT ON COLUMN customer_credential.secret_hash IS 'Argon2id hash of PIN / password / TOTP seed reference [SECRET]';
COMMENT ON COLUMN customer_credential.failed_attempts IS 'Consecutive failures';
COMMENT ON COLUMN customer_credential.locked_until IS 'Lockout end';
COMMENT ON COLUMN customer_credential.last_used_at IS 'Last successful use';
COMMENT ON COLUMN customer_credential.expires_at IS 'Expiry (password rotation policy)';
COMMENT ON COLUMN customer_credential.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN customer_credential.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN customer_credential.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN customer_credential.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN customer_credential.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_customer_credential_tenant ON customer_credential (tenant_id, created_at);
CREATE INDEX ix_customer_credential_customer_id ON customer_credential (customer_id);
CREATE INDEX ix_customer_credential_customer_device_id ON customer_credential (customer_device_id);
ALTER TABLE customer_credential ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON customer_credential USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_customer_credential_touch BEFORE UPDATE ON customer_credential FOR EACH ROW EXECUTE FUNCTION touch_row();

-- contact_verification: One-time-password challenge sent to verify a contact point; the code is kept only as a salted hash
CREATE TABLE contact_verification (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  customer_id                  uuid NOT NULL REFERENCES customer(id),
  customer_contact_id          uuid NOT NULL REFERENCES customer_contact(id),
  channel                      varchar(40) NOT NULL CHECK (channel IN ('SMS', 'EMAIL', 'WHATSAPP')),
  destination_masked           varchar(64) NOT NULL,
  code_hash                    varchar(255) NOT NULL,
  status                       varchar(40) NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'VERIFIED', 'EXPIRED', 'LOCKED', 'SUPERSEDED')),
  attempts                     integer NOT NULL DEFAULT 0,
  max_attempts                 integer NOT NULL DEFAULT 5,
  expires_at                   timestamptz NOT NULL,
  resend_available_at          timestamptz NOT NULL,
  locked_until                 timestamptz,
  verified_at                  timestamptz,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500)
);
COMMENT ON TABLE contact_verification IS 'One-time-password challenge sent to verify a contact point; the code is kept only as a salted hash';
COMMENT ON COLUMN contact_verification.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN contact_verification.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN contact_verification.created_at IS 'Creation time';
COMMENT ON COLUMN contact_verification.created_by IS 'Principal that created the row';
COMMENT ON COLUMN contact_verification.updated_at IS 'Last update time';
COMMENT ON COLUMN contact_verification.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN contact_verification.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN contact_verification.customer_id IS 'Customer';
COMMENT ON COLUMN contact_verification.customer_contact_id IS 'Contact point being verified';
COMMENT ON COLUMN contact_verification.channel IS 'Delivery channel';
COMMENT ON COLUMN contact_verification.destination_masked IS 'Masked phone number or email the code was sent to';
COMMENT ON COLUMN contact_verification.code_hash IS 'Salted hash of the one-time code [SECRET]';
COMMENT ON COLUMN contact_verification.status IS 'Challenge status';
COMMENT ON COLUMN contact_verification.attempts IS 'Wrong codes entered';
COMMENT ON COLUMN contact_verification.max_attempts IS 'Wrong codes allowed before the challenge locks';
COMMENT ON COLUMN contact_verification.expires_at IS 'Code expiry';
COMMENT ON COLUMN contact_verification.resend_available_at IS 'Earliest time a new code can be requested';
COMMENT ON COLUMN contact_verification.locked_until IS 'End of the lockout after too many wrong codes';
COMMENT ON COLUMN contact_verification.verified_at IS 'Time the code was confirmed';
COMMENT ON COLUMN contact_verification.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN contact_verification.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN contact_verification.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN contact_verification.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN contact_verification.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_contact_verification_tenant ON contact_verification (tenant_id, created_at);
CREATE INDEX ix_contact_verification_customer_id ON contact_verification (customer_id);
CREATE INDEX ix_contact_verification_customer_contact_id ON contact_verification (customer_contact_id);
ALTER TABLE contact_verification ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON contact_verification USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_contact_verification_touch BEFORE UPDATE ON contact_verification FOR EACH ROW EXECUTE FUNCTION touch_row();

-- consent: Consent given or withdrawn by a customer for a purpose and scope (GDPR, LGPD, DPDP, POPIA, open banking)
CREATE TABLE consent (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  customer_id                  uuid NOT NULL REFERENCES customer(id),
  purpose                      varchar(40) NOT NULL CHECK (purpose IN ('MARKETING', 'PROFILING', 'DATA_SHARING_THIRD_PARTY', 'OPEN_BANKING_AIS', 'OPEN_BANKING_PIS', 'CREDIT_BUREAU', 'BIOMETRIC_PROCESSING', 'TERMS_AND_CONDITIONS', 'PRIVACY_POLICY', 'LOCATION', 'ANALYTICS')),
  status                       varchar(40) NOT NULL DEFAULT 'GIVEN' CHECK (status IN ('GIVEN', 'WITHDRAWN', 'EXPIRED', 'REJECTED')),
  scope                        jsonb,
  recipient                    varchar(200),
  policy_version               varchar(32) NOT NULL,
  lawful_basis                 varchar(40),
  channel                      varchar(40) CHECK (channel IN ('MOBILE_APP', 'WEB', 'USSD', 'AGENT', 'BRANCH', 'API')),
  given_at                     timestamptz NOT NULL,
  expires_at                   timestamptz,
  withdrawn_at                 timestamptz,
  evidence                     jsonb,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500)
);
COMMENT ON TABLE consent IS 'Consent given or withdrawn by a customer for a purpose and scope (GDPR, LGPD, DPDP, POPIA, open banking)';
COMMENT ON COLUMN consent.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN consent.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN consent.created_at IS 'Creation time';
COMMENT ON COLUMN consent.created_by IS 'Principal that created the row';
COMMENT ON COLUMN consent.updated_at IS 'Last update time';
COMMENT ON COLUMN consent.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN consent.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN consent.customer_id IS 'Customer';
COMMENT ON COLUMN consent.purpose IS 'Purpose';
COMMENT ON COLUMN consent.status IS 'Status';
COMMENT ON COLUMN consent.scope IS 'Data categories, accounts or permissions covered';
COMMENT ON COLUMN consent.recipient IS 'Third party receiving data (open banking TPP, bureau)';
COMMENT ON COLUMN consent.policy_version IS 'Version of the policy / terms consented to';
COMMENT ON COLUMN consent.lawful_basis IS 'CONSENT, CONTRACT, LEGAL_OBLIGATION, LEGITIMATE_INTEREST';
COMMENT ON COLUMN consent.channel IS 'Channel where consent was captured';
COMMENT ON COLUMN consent.given_at IS 'Time consent was given';
COMMENT ON COLUMN consent.expires_at IS 'Expiry';
COMMENT ON COLUMN consent.withdrawn_at IS 'Withdrawal time';
COMMENT ON COLUMN consent.evidence IS 'Capture evidence: IP, device, screen version, text hash';
COMMENT ON COLUMN consent.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN consent.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN consent.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN consent.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN consent.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_consent_tenant ON consent (tenant_id, created_at);
CREATE INDEX ix_consent_customer_id ON consent (customer_id);
ALTER TABLE consent ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON consent USING (tenant_id = current_setting('app.tenant_id')::uuid);
