-- privacy_request: Data subject request (access, export, rectification, erasure) with statutory deadline
CREATE TABLE privacy_request (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  customer_id                  uuid NOT NULL REFERENCES customer(id),
  request_type                 varchar(40) NOT NULL CHECK (request_type IN ('ACCESS', 'EXPORT', 'RECTIFICATION', 'ERASURE', 'RESTRICTION', 'OBJECTION')),
  status                       varchar(40) NOT NULL DEFAULT 'RECEIVED' CHECK (status IN ('RECEIVED', 'VERIFYING_IDENTITY', 'IN_PROGRESS', 'COMPLETED', 'PARTIALLY_COMPLETED', 'REJECTED')),
  received_at                  timestamptz NOT NULL DEFAULT now(),
  due_at                       timestamptz NOT NULL,
  channel                      varchar(40) CHECK (channel IN ('MOBILE_APP', 'WEB', 'USSD', 'AGENT', 'BRANCH', 'API')),
  details                      text,
  assigned_to                  uuid,
  result_document_id           uuid,
  retention_blockers           jsonb,
  completed_at                 timestamptz,
  rejection_reason             varchar(255),
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500)
);
COMMENT ON TABLE privacy_request IS 'Data subject request (access, export, rectification, erasure) with statutory deadline';
COMMENT ON COLUMN privacy_request.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN privacy_request.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN privacy_request.created_at IS 'Creation time';
COMMENT ON COLUMN privacy_request.created_by IS 'Principal that created the row';
COMMENT ON COLUMN privacy_request.updated_at IS 'Last update time';
COMMENT ON COLUMN privacy_request.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN privacy_request.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN privacy_request.customer_id IS 'Customer';
COMMENT ON COLUMN privacy_request.request_type IS 'Request type';
COMMENT ON COLUMN privacy_request.status IS 'Status';
COMMENT ON COLUMN privacy_request.received_at IS 'Time received';
COMMENT ON COLUMN privacy_request.due_at IS 'Statutory deadline (e.g. 30 days)';
COMMENT ON COLUMN privacy_request.channel IS 'Channel';
COMMENT ON COLUMN privacy_request.details IS 'Customer''s request text';
COMMENT ON COLUMN privacy_request.assigned_to IS 'Handler';
COMMENT ON COLUMN privacy_request.result_document_id IS 'Export package or response letter';
COMMENT ON COLUMN privacy_request.retention_blockers IS 'Records that must be retained by law (not erased)';
COMMENT ON COLUMN privacy_request.completed_at IS 'Completion time';
COMMENT ON COLUMN privacy_request.rejection_reason IS 'Reason if rejected';
COMMENT ON COLUMN privacy_request.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN privacy_request.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN privacy_request.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN privacy_request.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN privacy_request.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_privacy_request_tenant ON privacy_request (tenant_id, created_at);
CREATE INDEX ix_privacy_request_customer_id ON privacy_request (customer_id);
CREATE INDEX ix_privacy_request_assigned_to ON privacy_request (assigned_to);
CREATE INDEX ix_privacy_request_result_document_id ON privacy_request (result_document_id);
ALTER TABLE privacy_request ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON privacy_request USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_privacy_request_touch BEFORE UPDATE ON privacy_request FOR EACH ROW EXECUTE FUNCTION touch_row();

-- Transactional outbox: events are written here in the same transaction as the
-- state change and relayed to Kafka by the outbox relay (Debezium).
CREATE TABLE outbox (
  id              uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id       uuid NOT NULL,
  aggregate_type  varchar(64) NOT NULL,
  aggregate_id    uuid NOT NULL,
  event_type      varchar(128) NOT NULL,
  payload         jsonb NOT NULL,
  headers         jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_outbox_created ON outbox (created_at);

-- Idempotency keys for POST requests (24h retention).
CREATE TABLE idempotency_key (
  tenant_id       uuid NOT NULL,
  key             varchar(128) NOT NULL,
  request_hash    varchar(64) NOT NULL,
  response_status integer,
  response_body   jsonb,
  created_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, key)
);

-- Runtime access for the non-superuser application role (RLS does not apply to superusers).
DO $$
BEGIN
  IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'meridian_app') THEN
    GRANT USAGE ON SCHEMA customer TO meridian_app;
    GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA customer TO meridian_app;
    ALTER DEFAULT PRIVILEGES IN SCHEMA customer GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO meridian_app;
  END IF;
END $$;
